//! Separate, account-free Podcasts: directory, recent episodes and local subscriptions.
use crate::{*,serde_json::{json,Value}};
trait Subtle { fn subtle(self)->Self; }
impl Subtle for Value { fn subtle(mut self)->Self { self["subtle"]=json!(true);self } }
const LIBRARY:&str="podcast_following";
const PREFS:&str="podcast_preferences";
const TOPICS:&[(&str,&str)]=&[("","All"),("news","News"),("comedy","Comedy"),("science","Science"),("history","History"),("business","Business"),("health","Health"),("music","Music"),("kids","Kids")];
fn search(s:&mut Value,offset:u64)->Value{s["view"]=json!("directory");s["tab"]=json!("directory");s["pending_offset"]=json!(offset);s["pending_query"]=s["query"].clone();s["pending_language"]=s["language"].clone();s["status"]=json!("");effect("podcasts.search",json!({"query":s["query"],"language":s["language"],"offset":offset}),"pod.found")}
fn feed(s:&mut Value,offset:u64)->Value{s["view"]=json!("show");s["pending_episode_offset"]=json!(offset);s["status"]=json!("");effect("podcasts.feed",json!({"feed":s["show"]["feed"],"offset":offset}),"pod.loaded")}
fn prefs(_s:&Value)->Value{collections::get(PREFS,"prefs","pod.prefs.before")}
fn show(s:&Value,url:&str)->Option<Value>{["results","library","sources","recent"].iter().flat_map(|k|s[*k].as_array().into_iter().flatten()).find(|r|r["feed"].as_str().is_some_and(|f|key(f)==url)).map(|r|json!({"title":r["show_title"].as_str().or(r["title"].as_str()).unwrap_or("Podcast"),"feed":r["feed"],"author":r["author"]}))}
fn play(s:&mut Value,row:Value)->Value{s["pending_episode"]=row.clone();s["status"]=json!("");effect("podcasts.play",json!({"feed":row["feed"],"episode":row["id"]}),"pod.played")}
pub fn controller(input:Value)->Value{
 let mut s=input["state"].clone();if !s.is_object(){s=json!({"view":"directory","tab":"directory","query":"","topic":"","language":"","results":[],"library":[],"sources":[],"recent":[],"revision":0,"library_next":null,"next":null,"offset":0,"episodes":[],"episode_offset":0,"episode_next":null,"show":null,"followed":false,"status":"","settings":false});}
 // Existing app installations retain their subscription collection.
 if s["tab"].as_str().is_none(){s["tab"]=json!("directory");}for k in["sources","recent"]{if !s[k].is_array(){s[k]=json!([])}}
 let e=&input["event"];let a=e["action"].as_str().unwrap_or("");let ok=e["reply"]["ok"]==true;let v=&e["reply"]["value"];let mut req=Value::Null;
 match a{
 "start"=>req=effect("podcasts.downloads",json!({}),"pod.downloads.loaded"),
 "pod.downloads.loaded"=>{if ok{s["downloads"]=v["downloads"].clone();}req=collections::get(PREFS,"prefs","pod.prefs.loaded");},
 "pod.prefs.loaded"=>{if ok{let data=v.get("data").filter(|d|d.is_object()).or_else(||v.get("item").and_then(|i|i.get("data"))).unwrap_or(&Value::Null);for k in["recent","sources"]{if data[k].is_array(){s[k]=json!(data[k].as_array().unwrap().iter().take(40).cloned().collect::<Vec<_>>());}}}req=collections::page(LIBRARY,"",None,"pod.initial");},
 "pod.initial"=>{if ok{s["revision"]=v["revision"].clone();s["library"]=json!(v["items"].as_array().into_iter().flatten().map(|x|x["data"].clone()).collect::<Vec<_>>());s["library_next"]=v["next"].clone();}req=search(&mut s,0)},
 "pod.query"=>{s["query"]=e["value"].clone();s["topic"]=json!("");},"pod.language"=>s["language"]=e["value"].clone(),
 "pod.topic"=>{s["topic"]=e["value"].clone();s["query"]=e["value"].clone();req=search(&mut s,0)},
 "pod.search"=>req=search(&mut s,0),"pod.discover"|"pod.browse"=>{s["tab"]=json!("directory");s["view"]=json!("directory");s["status"]=json!("");},
 "pod.recent"=>{s["view"]=json!("recent");s["tab"]=json!("recent");s["status"]=json!("");},
 "pod.back"=>{s["view"]=s["tab"].clone();s["status"]=json!("");},
 "pod.next"=>{if let Some(n)=s["next"].as_u64(){req=search(&mut s,n)}},"pod.previous"=>{let n=s["offset"].as_u64().unwrap_or(0).saturating_sub(20);req=search(&mut s,n)},
 "pod.found" if ok=>{s["offset"]=s["pending_offset"].clone();s["searched_query"]=s["pending_query"].clone();s["searched_language"]=s["pending_language"].clone();s["results"]=v["items"].clone();s["next"]=v["next"].clone();s["status"]=json!(if s["results"].as_array().is_none_or(Vec::is_empty){"No podcasts found. Try another topic or search."}else{""});},
 "pod.library"|"pod.library.first"=>{s["tab"]=json!("library");s["view"]=json!("library");s["library_page"]=json!(false);s["status"]=json!("");req=collections::page(LIBRARY,"",None,"pod.library.loaded")},
 "pod.library.more"=>{s["library_page"]=json!(true);req=collections::page(LIBRARY,s["library_next"].as_str().unwrap_or(""),s["revision"].as_u64(),"pod.library.loaded")},
 "pod.library.loaded" if ok=>{s["revision"]=v["revision"].clone();s["library"]=json!(v["items"].as_array().into_iter().flatten().map(|x|x["data"].clone()).collect::<Vec<_>>());s["library_next"]=v["next"].clone();},
 "pod.settings"=>{s["source_error"]=json!("");s["settings"]=json!(true);s["status"]=json!("");},"pod.settings.close"=>s["settings"]=json!(false),
 "pod.feed.url"=>s["custom_feed"]=e["value"].clone(),
 "pod.feed.add" if !public_feed(s["custom_feed"].as_str().unwrap_or("").trim())=>{s["source_error"]=json!("Enter a public HTTPS podcast RSS URL.");},
 "pod.feed.add"=>{s["source_error"]=json!("");s["show"]=json!({"title":"Podcast","feed":s["custom_feed"].as_str().unwrap_or("").trim()});s["show"]["valid"]=json!(false);s["episodes"]=json!([]);s["episode_next"]=Value::Null;s["adding_source"]=json!(true);s["settings"]=json!(false);req=feed(&mut s,0)},
 _ if a.starts_with("pod.source.remove.")=>{let id=&a[18..];s["sources"]=json!(s["sources"].as_array().into_iter().flatten().filter(|r|key(r["feed"].as_str().unwrap_or(""))!=id).cloned().collect::<Vec<_>>());req=prefs(&s);},
 _ if a.starts_with("pod.open.")||a.starts_with("pod.source.open.")||a.starts_with("pod.settings.open.")=>{let id=a.strip_prefix("pod.open.").or_else(||a.strip_prefix("pod.source.open.")).or_else(||a.strip_prefix("pod.settings.open.")).unwrap();if let Some(row)=show(&s,id){s["show"]=row;s["show"]["valid"]=json!(false);s["followed"]=json!(false);s["episodes"]=json!([]);s["episode_next"]=Value::Null;s["settings"]=json!(false);s["adding_source"]=json!(false);req=feed(&mut s,0)}},
 "pod.refresh"=>req=feed(&mut s,0),"pod.episodes.next"=>{if let Some(n)=s["episode_next"].as_u64(){req=feed(&mut s,n)}},"pod.episodes.previous"=>{let n=s["episode_offset"].as_u64().unwrap_or(0).saturating_sub(20);req=feed(&mut s,n)},
 "pod.loaded" if ok=>{s["show"]["valid"]=json!(true);s["show"]["title"]=v["title"].clone();s["episodes"]=v["items"].clone();s["episode_offset"]=s["pending_episode_offset"].clone();s["episode_next"]=v["next"].clone();s["status"]=json!(if s["episodes"].as_array().is_none_or(Vec::is_empty){"No playable episodes in this feed. Try Refresh or another podcast."}else{""});req=collections::get(LIBRARY,&key(s["show"]["feed"].as_str().unwrap_or("")),"pod.follow.checked")},
 "pod.follow.checked" if ok=>{s["followed"]=json!(v["data"].is_object());if s["adding_source"]==true{s["adding_source"]=json!(false);let mut rows=vec![s["show"].clone()];rows.extend(s["sources"].as_array().into_iter().flatten().filter(|r|r["feed"]!=s["show"]["feed"]).take(39).cloned());s["sources"]=json!(rows);req=prefs(&s);}},
 "pod.follow"=>req=collections::get(LIBRARY,&key(s["show"]["feed"].as_str().unwrap_or("")),"pod.follow.before"),
 "pod.follow.before" if ok=>{s["removing"]=json!(v["data"].is_object());let k=key(s["show"]["feed"].as_str().unwrap_or(""));req=collections::transact(LIBRARY,v["revision"].as_u64().unwrap_or(0),1,None,vec![if v["data"].is_object(){collections::delete(&k)}else{collections::put(&k,s["show"].clone())}],"pod.follow.saved")},
 "pod.follow.saved" if ok=>{s["followed"]=json!(s["removing"]!=true);s["status"]=json!("");req=collections::page(LIBRARY,"",None,"pod.library.loaded");},
 _ if a.starts_with("pod.play.")||a.starts_with("pod.episode.play.")=>{let id=a.strip_prefix("pod.play.").or_else(||a.strip_prefix("pod.episode.play.")).unwrap();if let Some(row)=s["episodes"].as_array().into_iter().flatten().find(|r|r["id"]==id){let mut row=row.clone();row["feed"]=s["show"]["feed"].clone();row["show_title"]=s["show"]["title"].clone();req=play(&mut s,row)}},
 _ if a.starts_with("pod.replay.")||a.starts_with("pod.recent.play.")=>{let id=a.strip_prefix("pod.replay.").or_else(||a.strip_prefix("pod.recent.play.")).unwrap();if let Some(row)=s["recent"].as_array().into_iter().flatten().find(|r|r["id"]==id).cloned(){req=play(&mut s,row)}},
 _ if a.starts_with("pod.save.")||a.starts_with("pod.recent.save.")=>{let recent=a.starts_with("pod.recent.save.");let id=a.strip_prefix("pod.recent.save.").or_else(||a.strip_prefix("pod.save.")).unwrap();if let Some(row)=s[if recent{"recent"}else{"episodes"}].as_array().into_iter().flatten().find(|r|r["id"]==id).cloned(){let saved=s["downloads"].as_array().into_iter().flatten().any(|r|r==id);s["downloading"]=if saved{Value::Null}else{json!(id)};s["status"]=json!("");req=effect(if saved{"podcasts.delete"}else{"podcasts.download"},json!({"feed":if recent{row["feed"].clone()}else{s["show"]["feed"].clone()},"episode":id}),"pod.download.changed");}},
 "pod.download.changed"=>{s["downloading"]=Value::Null;if ok{s["downloads"]=v["downloads"].clone();s["status"]=json!("");}},
 "pod.retry"=>{if s["pending_episode"].is_object(){let row=s["pending_episode"].clone();req=play(&mut s,row)}},
 "pod.played" if ok=>{let row=s["pending_episode"].clone();s["current"]=row.clone();let mut recent=vec![row.clone()];recent.extend(s["recent"].as_array().into_iter().flatten().filter(|r|r["id"]!=row["id"]).take(39).cloned());s["recent"]=json!(recent);req=prefs(&s)},
 "pod.clear"=>s["confirm_clear"]=json!(true),"pod.clear.cancel"=>s["confirm_clear"]=json!(false),"pod.clear.accept"=>{s["confirm_clear"]=json!(false);s["recent"]=json!([]);req=prefs(&s)},
 "pod.prefs.before" if ok=>req=collections::transact(PREFS,v["revision"].as_u64().unwrap_or(0),1,None,vec![collections::put("prefs",json!({"recent":s["recent"],"sources":s["sources"]}))],"pod.prefs.saved"),
 _=>{}
 }
 if e["reply"]["ok"]==false{s["status"]=json!(match a{"pod.follow.saved"=>"Subscription change not saved. Try again.","pod.loaded"=>"Couldn't load episodes. Retry, go back, or add another RSS source in settings.","pod.download.changed"=>"Download could not finish. Check your connection and free space, then try again.","pod.played"=>"Couldn't play this episode. Try again or choose another episode.","pod.prefs.saved"=>"Recent episodes or sources couldn't be saved. Your subscriptions are kept.",_=>"Couldn't complete this request. Try again; your saved podcasts are kept."});}
 let view=s["view"].as_str().unwrap_or("directory").to_string();let tab=s["tab"].as_str().unwrap_or("directory").to_string();let mut nodes=Vec::new();
 for(id,t,value)in[("pod.discover","Browse","directory"),("pod.recent","Recent","recent"),("pod.library","Podcasts","library")]{let mut n=button(id,t).row("pod.tabs");n["tab"]=json!(true);n["selected"]=json!(tab==value);nodes.push(n);}
 match view.as_str(){
 "show"=>{nodes.push(button("pod.back","Back to podcasts").subtle());nodes.push(primary_button("pod.follow",if s["followed"]==true{"Unsubscribe"}else{"Subscribe"}).enabled(s["show"]["valid"]==true));nodes.push(button("pod.refresh","Refresh episodes").subtle());let mut title=heading("pod.show.title",s["show"]["title"].as_str().unwrap_or("Podcast"));title["font"]=json!(22);nodes.push(title);for row in s["episodes"].as_array().into_iter().flatten(){if let(Some(id),Some(t))=(row["id"].as_str(),row["title"].as_str()){nodes.push(episode_row(&s,id,t,&episode_detail(row),false));}}if s["episode_offset"].as_u64().unwrap_or(0)>0{nodes.push(button("pod.episodes.previous","Newer episodes"));}if s["episode_next"].is_number(){nodes.push(button("pod.episodes.next","More episodes"));}},
 "recent"=>{if s["recent"].as_array().is_none_or(Vec::is_empty){nodes.push(label("pod.recent.empty","No recent episodes"));nodes.push(button("pod.browse","Browse podcasts"));}else{for row in s["recent"].as_array().into_iter().flatten(){if let(Some(id),Some(t))=(row["id"].as_str(),row["title"].as_str()){nodes.push(episode_row(&s,id,t,row["show_title"].as_str().unwrap_or("Podcast"),true));}}nodes.push(button("pod.clear","Clear recent episodes").subtle());}},
 "library"=>{if s["library"].as_array().is_none_or(Vec::is_empty){nodes.push(label("pod.empty","No subscriptions yet"));nodes.push(button("pod.browse","Browse podcasts"));}shows(&mut nodes,&s["library"]);if s["library_next"].is_string(){nodes.push(button("pod.library.more","More subscriptions"));}if s["library_page"]==true{nodes.push(button("pod.library.first","First subscriptions"));}},
 _=>{nodes.push(field("pod.query","Search podcasts or creators",s["query"].as_str().unwrap_or("")).limit(80));nodes.push(choices("chips","pod.topic","Browse topics",s["topic"].as_str().unwrap_or(""),TOPICS));let mut lang=choices("select","pod.language","Language",s["language"].as_str().unwrap_or(""),&[("","Any language"),("en","English"),("es","Spanish"),("de","German"),("fr","French"),("pt","Portuguese"),("it","Italian"),("nl","Dutch")]);lang["compact"]=json!(true);nodes.push(lang);nodes.push(primary_button("pod.search","Find podcasts"));if !s["sources"].as_array().is_none_or(Vec::is_empty)&&s["query"].as_str().unwrap_or("").is_empty(){nodes.push(heading("pod.sources.title","Added podcasts"));for r in s["sources"].as_array().into_iter().flatten().take(10){if let Some(url)=r["feed"].as_str(){nodes.push(record(&format!("pod.source.open.{}",key(url)),r["title"].as_str().unwrap_or("Podcast"),""));}}}shows(&mut nodes,&s["results"]);let same=s["query"]==s["searched_query"]&&s["language"]==s["searched_language"];if s["offset"].as_u64().unwrap_or(0)>0{nodes.push(button("pod.previous","Previous podcasts").enabled(same));}if s["next"].is_number(){nodes.push(button("pod.next","More podcasts").enabled(same));}}
 }
 if s["status"].as_str().is_some_and(|s|!s.is_empty()){nodes.push(label("pod.status",s["status"].as_str().unwrap()));}
 let mut player=media::player("pod.player");player["dock"]=json!(true);player["podcast"]=json!(true);if s["current"].is_object(){player["title"]=s["current"]["title"].clone();player["retry"]=json!("pod.retry");}nodes.push(player);
 let settings=s["settings"]==true;let clear=s["confirm_clear"]==true;let mut menu=vec![heading("pod.settings.sources","Podcast sources"),field("pod.feed.url","Podcast RSS URL",s["custom_feed"].as_str().unwrap_or("")).limit(2048),primary_button("pod.feed.add","Add podcast"),label("pod.settings.info","Search the directory or add a podcast RSS feed.")];for row in s["sources"].as_array().into_iter().flatten(){if let Some(url)=row["feed"].as_str(){menu.push(record(&format!("pod.settings.open.{}",key(url)),row["title"].as_str().unwrap_or("Podcast"),"").trailing(&format!("pod.source.remove.{}",key(url)),"Remove source","delete"));}}
 if s["source_error"].as_str().is_some_and(|v|!v.is_empty()){menu.push(label("pod.source.error",s["source_error"].as_str().unwrap()));}menu.push(button("pod.settings.close","Done").subtle());
 let mut screen=Screen::new("Podcasts",s).body(nodes).actions(vec![icon("pod.settings","Podcast settings","settings")]).scrollable().scroll_key(&format!("pod.{view}.{tab}" )).effect(req);if view=="show"{screen=screen.back("pod.back");}if settings{screen=screen.dialog("Podcast settings","pod.settings.close",menu);}if clear{screen=screen.confirm_labeled("Clear recent episodes?","Subscriptions and playback are kept.","pod.clear.accept","pod.clear.cancel","Clear");}screen.finish()
}
// Early field feedback; the host still validates DNS and every redirect.
fn public_feed(url:&str)->bool{
 if url.len()>2048||url.chars().any(|c|c.is_whitespace()||c.is_control()||c=='\\')||url.contains('#'){return false}
 let Some(rest)=url.strip_prefix("https://")else{return false};let authority=rest.split(['/', '?']).next().unwrap_or("").to_ascii_lowercase();let host=authority.strip_suffix(":443").unwrap_or(&authority);
 host.len()<=253&&host.contains('.')&&!host.ends_with(".local")&&!host.ends_with(".localhost")&&!host.bytes().all(|b|b.is_ascii_digit()||b==b'.')&&host.split('.').all(|p|!p.is_empty()&&p.len()<=63&&!p.starts_with('-')&&!p.ends_with('-')&&p.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'))
}
fn episode_row(s:&Value,id:&str,title:&str,detail:&str,recent:bool)->Value{let saved=s["downloads"].as_array().into_iter().flatten().any(|r|r==id);let busy=s["downloading"]==id;let mut n=record(&format!("{}.{id}",if recent{"pod.replay"}else{"pod.play"}),title,&format!("{detail}{}",if saved{" · Downloaded"}else{""})).trailing(&format!("{}.{id}",if recent{"pod.recent.play"}else{"pod.episode.play"}),"Play episode","play");n["podcast_episode"]=json!(id);n["downloaded"]=json!(saved);n["secondary_trailing"]=json!({"id":format!("{}.{id}",if recent{"pod.recent.save"}else{"pod.save"}),"text":if busy{"Downloading episode"}else if saved{"Delete download"}else{"Download episode"},"icon":if saved{"delete"}else{"download"},"spinning":busy});n}
fn episode_detail(r:&Value)->String{let date=r["date"].as_str().unwrap_or("");let date=if date.len()>16{&date[..date.char_indices().map(|(i,_)|i).take_while(|i|*i<=16).last().unwrap_or(0)]}else{date};[date,r["duration"].as_str().unwrap_or("")].into_iter().filter(|s|!s.is_empty()).collect::<Vec<_>>().join(" · ")}
fn key(url:&str)->String{let mut a=0xcbf29ce484222325u64;let mut b=0x84222325cbf29ce4u64;for c in url.bytes(){a=(a^c as u64).wrapping_mul(0x100000001b3);b=(b^c as u64).wrapping_mul(0x100000001b3)}format!("{a:016x}{b:016x}")}
fn shows(nodes:&mut Vec<Value>,rows:&Value){for r in rows.as_array().into_iter().flatten(){if let(Some(feed),Some(t))=(r["feed"].as_str(),r["title"].as_str()){nodes.push(record(&format!("pod.open.{}",key(feed)),t,r["author"].as_str().unwrap_or("")));}}}
#[cfg(test)]mod tests{use super::*;
fn step(s:Value,a:&str,v:Value)->Value{controller(json!({"state":s,"event":{"action":a,"reply":{"ok":true,"value":v}}}))}
#[test]fn three_tabs_are_pinned_and_clean(){let f=controller(json!({}));let tabs:Vec<_>=f["body"].as_array().unwrap().iter().filter(|n|n["tab"]==true).map(|n|n["text"].as_str().unwrap()).collect();assert_eq!(tabs,vec!["Browse","Recent","Podcasts"]);assert!(!f["body"].to_string().contains("No sign-in"));let f=step(f["state"].clone(),"pod.recent",Value::Null);assert!(!f["body"].to_string().contains("pod.topic"));}
#[test]fn recent_is_saved_only_after_play_success_and_plays_without_subscription(){let id="a".repeat(64);let mut s=controller(json!({}))["state"].clone();s["show"]=json!({"feed":"https://example.org/rss","title":"Show"});s["episodes"]=json!([{"id":id,"title":"Episode"}]);let f=step(s,&format!("pod.play.{id}"),Value::Null);assert_eq!(f["effect"]["service"],"podcasts.play");assert_eq!(f["state"]["recent"],json!([]));let f=step(f["state"].clone(),"pod.played",json!({}));assert_eq!(f["state"]["recent"][0]["title"],"Episode");assert_eq!(f["effect"]["service"],"collections.get");assert!(f["state"]["library"].as_array().unwrap().is_empty());let f=step(f["state"].clone(),"pod.recent",Value::Null);let f=step(f["state"].clone(),&format!("pod.replay.{id}"),Value::Null);assert_eq!(f["effect"]["args"]["feed"],"https://example.org/rss");}
#[test]fn failed_feed_has_back_and_retry_and_never_subscribes(){let mut s=controller(json!({}))["state"].clone();s["view"]=json!("show");let f=controller(json!({"state":s,"event":{"action":"pod.loaded","reply":{"ok":false}}}));assert_eq!(f["back_action"],"pod.back");assert!(f["body"].as_array().unwrap().iter().any(|r|r["id"]=="pod.refresh"));assert!(f["state"]["library"].as_array().unwrap().is_empty());let f=step(f["state"].clone(),"pod.back",Value::Null);assert_eq!(f["state"]["view"],"directory");}
#[test]fn settings_and_saved_sources_survive_restart(){let f=step(Value::Null,"pod.prefs.loaded",json!({"data":{"sources":[{"title":"Added","feed":"https://example.org/rss"}],"recent":[]}}));assert_eq!(f["state"]["sources"][0]["title"],"Added");let f=step(f["state"].clone(),"pod.settings",Value::Null);assert_eq!(f["menu_title"],"Podcast settings");assert!(f["menu"].to_string().contains("Add podcast"));}
#[test]fn download_controls_switch_spinner_remove_and_recent_without_subscription(){let id="a".repeat(64);let mut s=controller(json!({}))["state"].clone();s["view"]=json!("show");s["show"]=json!({"feed":"https://example.org/rss","title":"Show"});s["episodes"]=json!([{"id":id,"title":"Episode"}]);let f=step(s,&format!("pod.save.{id}"),Value::Null);assert_eq!(f["effect"]["service"],"podcasts.download");assert!(f["body"].as_array().unwrap().iter().any(|r|r["secondary_trailing"]["spinning"]==true));let f=step(f["state"].clone(),"pod.download.changed",json!({"downloads":[id]}));assert!(f["body"].as_array().unwrap().iter().any(|r|r["secondary_trailing"]["icon"]=="delete"));let f=step(f["state"].clone(),&format!("pod.save.{id}"),Value::Null);assert_eq!(f["effect"]["service"],"podcasts.delete");let f=controller(json!({"state":f["state"],"event":{"action":"pod.download.changed","reply":{"ok":false}}}));assert!(f["state"]["downloading"].is_null());assert_eq!(f["state"]["downloads"],json!([id]));}

}
